import { APP_ID, inject, Injectable } from '@angular/core';

/**
 * Keeps track of the ID count per prefix. This helps us make the IDs a bit more deterministic.
 */
let counters: Record<string, number> = {};

/**
 * Service that generates unique IDs for DOM nodes.
 * Note that this service should not be used inside templates and should only be used within classes or else id will change with every render.
 * @docs {@link https://design.visa.com/developing/angular/services/id-generator | See docs}
 */
@Injectable({ providedIn: 'root' })
export class IdGenerator {
  private readonly appId: null | string = inject(APP_ID, { optional: true });

  /**
   * Generates a unique ID with a specific prefix.
   * @param prefix Prefix to add to the ID.
   */
  public newId(prefix: string = ''): string {
    // Omit the app ID if it's the default `ng`. Since the vast majority of pages have one
    // Angular app on them, we can reduce the amount of breakages by not adding it.
    if (this.appId && this.appId !== 'ng') prefix = `${this.appId}-${prefix}`;
    if (!counters.hasOwnProperty(prefix)) counters[prefix] = 0;
    return `${prefix}-${counters[prefix]++}`;
  }

  /**
   * Resets the counters for the IDs.
   * This is useful when testing to ensure that the IDs are deterministic.
   * @deprecated WARNING: This should only be used in tests. Do NOT use this in an actual application.
   */
  public static reset(): void {
    counters = {};
  }
}

